// Phase 11C — the SIZED artwork the app actually ships for the student rank / stage visuals.
//
// The owner masters (the six 1254² rank PNGs and the twenty-five 512² stage PNGs) are never imported by the app:
// every rank / stage image is served from its square, lossless, area-averaged derivatives in each folder's `sized/`
// (generated by scripts/generate-student-visual-derivatives.mjs). A consumer states the CSS size it displays the
// image at and receives a `src` sharp enough for a 2× screen plus a `srcSet` the browser picks from for 1×–3×, so a
// 40 px badge downloads a ~5–20 KB file instead of a 0.3–2 MB master. Presentation only: no rank / stage meaning here.

/** Square edge lengths of the shipped derivatives. Keep in sync with SIZES in the generator script. */
export const VISUAL_SIZES = [48, 96, 144, 256] as const;
export type VisualSize = (typeof VISUAL_SIZES)[number];
/** One artwork's derivatives, by edge length. */
export type VisualImageSet = Readonly<Record<VisualSize, string>>;
/** What an <img> needs: a 2×-sharp `src`, the candidate list and the CSS size the browser should size them for. */
export type VisualImgProps = { src: string; srcSet: string; sizes: string };

/**
 * Collect one artwork's derivatives from an eager `import.meta.glob` of its `sized/` folder. Keys look like
 * "<folder>/sized/stage-07-96.png". A missing size is left as "" (the guards and tests fail on it).
 */
export function sizedImageSet(glob: Record<string, string>, stem: string): VisualImageSet {
  const bySuffix = (size: number) => Object.entries(glob).find(([path]) => path.endsWith("/" + stem + "-" + size + ".png"))?.[1] || "";
  return Object.fromEntries(VISUAL_SIZES.map(size => [size, bySuffix(size)])) as unknown as VisualImageSet;
}

/**
 * The <img> sources for an artwork displayed at `displayPx` CSS pixels (square). `src` is the smallest derivative
 * covering a 2× screen (so a plain `src` is already crisp on most phones); `srcSet` lists only the derivatives from
 * the one covering 1× up to the one covering 3× — never anything larger — so no screen fetches a needlessly big file.
 * `sizes` defaults to the fixed display size; a responsive consumer passes its own media-query list.
 */
export function visualImgProps(set: VisualImageSet, displayPx: number, sizes: string = displayPx + "px"): VisualImgProps {
  const cover = (px: number) => VISUAL_SIZES.find(s => s >= px) ?? VISUAL_SIZES[VISUAL_SIZES.length - 1];
  const lo = cover(displayPx), hi = cover(displayPx * 3);
  const candidates = VISUAL_SIZES.filter(s => s >= lo && s <= hi);
  return { src: set[cover(displayPx * 2)], srcSet: candidates.map(s => set[s] + " " + s + "w").join(", "), sizes };
}
